public class DocCoverageValidatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        String clampDoc = "/**\n"
                + " * Clamps a value.\n"
                + " * @param value the input\n"
                + " */";
        String fullDoc = "/**\n"
                + " * Clamps a value.\n"
                + " * @param value the input\n"
                + " * @param low the floor\n"
                + " * @param high the ceiling\n"
                + " * @return the clamped value\n"
                + " */";
        String clampSig = "public static int clamp(int value, int low, int high)";

        check("three parameter names", "[value, low, high]",
                DocCoverageValidator.parameterNames(clampSig).toString());
        check("no parameters", "[]",
                DocCoverageValidator.parameterNames("public void reset()").toString());
        check("varargs and arrays", "[separator, parts]",
                DocCoverageValidator.parameterNames("public static String join(String separator, String... parts)").toString());
        check("two tags missing", "[low, high]",
                DocCoverageValidator.missingParamTags(clampSig, clampDoc).toString());
        check("nothing missing", "[]",
                DocCoverageValidator.missingParamTags(clampSig, fullDoc).toString());
        check("return tag needed", true, DocCoverageValidator.needsReturnTag(clampSig, clampDoc));
        check("return tag present", false, DocCoverageValidator.needsReturnTag(clampSig, fullDoc));
        check("void method needs no return tag", false,
                DocCoverageValidator.needsReturnTag("public void reset(int seed)", "/** Resets. */"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

