public class DocCoverageValidator {

    public static java.util.List<String> parameterNames(String signature) {
        java.util.List<String> names = new java.util.ArrayList<>();
        if (signature == null) {
            return names;
        }
        int open = signature.indexOf('(');
        int close = signature.lastIndexOf(')');
        if (open < 0 || close < open) {
            return names;
        }
        String inside = signature.substring(open + 1, close).trim();
        if (inside.isEmpty()) {
            return names;
        }
        for (String parameter : inside.split(",")) {
            String[] words = parameter.trim().split("\\s+");
            names.add(words[words.length - 1]);
        }
        return names;
    }

    public static java.util.List<String> missingParamTags(String signature, String docComment) {
        java.util.List<String> missing = new java.util.ArrayList<>();
        for (String name : parameterNames(signature)) {
            if (!hasTag(docComment, "@param " + name)) {
                missing.add(name);
            }
        }
        return missing;
    }

    public static boolean needsReturnTag(String signature, String docComment) {
        if (signature == null) {
            return false;
        }
        int open = signature.indexOf('(');
        if (open < 0) {
            return false;
        }
        String[] words = signature.substring(0, open).trim().split("\\s+");
        if (words.length < 2) {
            return false;
        }
        String returnType = words[words.length - 2];
        if (returnType.equals("void")) {
            return false;
        }
        return !hasTag(docComment, "@return");
    }

    private static boolean hasTag(String docComment, String tag) {
        if (docComment == null) {
            return false;
        }
        for (String raw : docComment.split("\n", -1)) {
            String line = raw.trim();
            if (line.startsWith("/**")) {
                line = line.substring(3).trim();
            } else if (line.startsWith("*")) {
                line = line.substring(1).trim();
            }
            if (line.equals(tag) || line.startsWith(tag + " ")) {
                return true;
            }
        }
        return false;
    }
}
